/** Soft-delete: the file is MOVED (never destroyed) to data/trash/chips. */
export async function deleteChip(slug: string, id: string): Promise<boolean> {
  const filePath = chipPath(slug, id);
  try {
    await fs.access(filePath);
  } catch {
    return false;
  }

  const trashPath = path.join(root(), 'data', 'trash', 'chips', slug, `${id}-${Date.now()}.json`);
  await fs.mkdir(path.dirname(trashPath), { recursive: true });
  try {
    await fs.rename(filePath, trashPath);
  } catch {
    await fs.copyFile(filePath, trashPath);
    await fs.unlink(filePath);
  }
  return true;
}

