 * root — trash/<slug>/<id>-<timestamp>.json — so dev/test instances remain
 * isolated from production and a deletion is always recoverable by hand.
 * Returns false when the file does not exist.
 */
export async function deleteConversation(
  slug: string,
  id: string,
): Promise<boolean> {
  const filePath = conversationPath(slug, id);
  try {
    await fs.access(filePath);
  } catch {
    return false;
  }

  const trashPath = path.join(dataRoot(), 'trash', slug, `${id}-${Date.now()}.json`);
  await fs.mkdir(path.dirname(trashPath), { recursive: true });
  try {
    await fs.rename(filePath, trashPath);
  } catch {
    // rename can fail across devices/filesystems — fall back to copy + unlink.
    await fs.copyFile(filePath, trashPath);
    await fs.unlink(filePath);
  }

  // The file no longer exists at filePath (moved to trash) — drop any cached
  // entry for it so a subsequent readConversationFile() call correctly stats
  // (fails) and returns null, instead of serving a stale cached hit.
