import path from 'node:path';
import { access, mkdtemp, mkdir, readFile, readdir, realpath, rm, writeFile } from 'node:fs/promises';

let temporaryRoot = '';
let isolatedDataRoot = '';
let previousWorkstationRoot: string | undefined;
let previousDataRoot: string | undefined;
let store!: typeof import('./conversationStore');

beforeAll(async () => {
  temporaryRoot = await realpath(await mkdtemp(path.join(os.tmpdir(), 'ws-conversation-trash-')));
  isolatedDataRoot = path.join(temporaryRoot, 'isolated-data');
  previousWorkstationRoot = process.env.WORKSTATION_ROOT;
  previousDataRoot = process.env.WORKSTATION_DATA_ROOT;
  process.env.WORKSTATION_ROOT = temporaryRoot;
  process.env.WORKSTATION_DATA_ROOT = isolatedDataRoot;
  store = await import('./conversationStore');
});

afterAll(async () => {
  if (previousWorkstationRoot === undefined) delete process.env.WORKSTATION_ROOT;
  else process.env.WORKSTATION_ROOT = previousWorkstationRoot;
  if (previousDataRoot === undefined) delete process.env.WORKSTATION_DATA_ROOT;
  else process.env.WORKSTATION_DATA_ROOT = previousDataRoot;
  await rm(temporaryRoot, { recursive: true, force: true });
});

describe('deleteConversation — active data root isolation', () => {
  test('moves the conversation under WORKSTATION_DATA_ROOT/trash', async () => {
    const slug = 'isolated-project';
    const id = '2026-09-15-isolated-trash';
    const sourcePath = path.join(isolatedDataRoot, 'conversations', slug, `${id}.json`);
    const source = JSON.stringify({ id, proof: 'isolated trash' });
    await mkdir(path.dirname(sourcePath), { recursive: true });
    await writeFile(sourcePath, source, 'utf8');

    expect(await store.deleteConversation(slug, id)).toBe(true);

    const trashDirectory = path.join(isolatedDataRoot, 'trash', slug);
    const trashFiles = await readdir(trashDirectory);
    expect(trashFiles).toHaveLength(1);
    expect(trashFiles[0]).toMatch(new RegExp(`^${id}-\\d+\\.json$`));
    expect(await readFile(path.join(trashDirectory, trashFiles[0]), 'utf8')).toBe(source);
    await expect(access(sourcePath)).rejects.toMatchObject({ code: 'ENOENT' });

    const productionShapedTrash = path.join(temporaryRoot, 'data', 'trash');
    await expect(access(productionShapedTrash)).rejects.toMatchObject({ code: 'ENOENT' });
  });
});
