import { afterAll, beforeAll, describe, expect, test } from 'bun:test';
import os from 'node:os';
import path from 'node:path';
import { access, mkdtemp, mkdir, readFile, readdir, realpath, rm, writeFile } from 'node:fs/promises';

// Twin of conversationStore.trash.test.ts for the chip and task stores: a
// soft-delete must land under the ACTIVE data root (WORKSTATION_DATA_ROOT),
// never under <WORKSTATION_ROOT>/data/trash.

let temporaryRoot = '';
let isolatedDataRoot = '';
let previousWorkstationRoot: string | undefined;
let previousDataRoot: string | undefined;
let chipStore!: typeof import('./chipStore');
let taskStore!: typeof import('./taskStore');

beforeAll(async () => {
  temporaryRoot = await realpath(await mkdtemp(path.join(os.tmpdir(), 'ws-chip-task-trash-')));
  isolatedDataRoot = path.join(temporaryRoot, 'isolated-data');
  previousWorkstationRoot = process.env.WORKSTATION_ROOT;
  previousDataRoot = process.env.WORKSTATION_DATA_ROOT;
  process.env.WORKSTATION_ROOT = temporaryRoot;
  process.env.WORKSTATION_DATA_ROOT = isolatedDataRoot;
  chipStore = await import('./chipStore');
  taskStore = await import('./taskStore');
});

afterAll(async () => {
  if (previousWorkstationRoot === undefined) delete process.env.WORKSTATION_ROOT;
  else process.env.WORKSTATION_ROOT = previousWorkstationRoot;
  if (previousDataRoot === undefined) delete process.env.WORKSTATION_DATA_ROOT;
  else process.env.WORKSTATION_DATA_ROOT = previousDataRoot;
  await rm(temporaryRoot, { recursive: true, force: true });
});

async function expectMovedToIsolatedTrash(kind: 'chips' | 'tasks', slug: string, id: string, sourcePath: string, source: string) {
  const trashDirectory = path.join(isolatedDataRoot, 'trash', kind, slug);
  const trashFiles = await readdir(trashDirectory);
  expect(trashFiles).toHaveLength(1);
  expect(trashFiles[0]).toMatch(new RegExp(`^${id}-\\d+\\.json$`));
  expect(await readFile(path.join(trashDirectory, trashFiles[0]), 'utf8')).toBe(source);
  await expect(access(sourcePath)).rejects.toMatchObject({ code: 'ENOENT' });
  await expect(access(path.join(temporaryRoot, 'data', 'trash'))).rejects.toMatchObject({ code: 'ENOENT' });
}

describe('deleteChip — active data root isolation', () => {
  test('moves the chip under WORKSTATION_DATA_ROOT/trash/chips', async () => {
    const slug = 'isolated-project';
    const id = '2026-09-24-isolated-chip-trash';
    const sourcePath = path.join(isolatedDataRoot, 'chips', slug, `${id}.json`);
    const source = JSON.stringify({ id, proof: 'isolated chip trash' });
    await mkdir(path.dirname(sourcePath), { recursive: true });
    await writeFile(sourcePath, source, 'utf8');

    expect(await chipStore.deleteChip(slug, id)).toBe(true);
    await expectMovedToIsolatedTrash('chips', slug, id, sourcePath, source);
  });

  test('returns false for a missing chip without creating any trash', async () => {
    expect(await chipStore.deleteChip('isolated-project', '2026-09-24-absent')).toBe(false);
    await expect(access(path.join(temporaryRoot, 'data'))).rejects.toMatchObject({ code: 'ENOENT' });
  });
});

describe('deleteTask — active data root isolation', () => {
  test('moves the task under WORKSTATION_DATA_ROOT/trash/tasks', async () => {
    const slug = 'isolated-project';
    const id = 'isolated-task-trash';
    const sourcePath = path.join(isolatedDataRoot, 'tasks', slug, `${id}.json`);
    const source = JSON.stringify({ id, proof: 'isolated task trash' });
    await mkdir(path.dirname(sourcePath), { recursive: true });
